## Code Example
```javascript
// Pseudo routing score
function score(model, tenant) {
  const cost = model.price * tenant.maxBudgetFactor;
  const latency = model.latencyMs <= tenant.latencySLO ? 0 : 1;
  const capability = model.capabilityScore;
  return wCost*cost + wLat*latency + wCap* (1 - capability);
}
```

